# Agent-callable tools (implement any TODO stubs) — generated by graphical-agents from the Graph IR (critic_loop_workflow).


def _check_python_syntax_impl(code: str) -> str:
    import ast

    try:
        ast.parse(code)
    except SyntaxError as exc:
        return f"SyntaxError: {exc.msg} (line {exc.lineno})"
    return "OK"


def check_python_syntax(code: str) -> str:
    """Check whether a Python source string parses. Returns 'OK', or the SyntaxError message with its line number."""
    return _check_python_syntax_impl(code)


def run_tool_agent(agent, prompt: str):
    """Run a tool-calling agent on one prompt (ADR-0059).

    Returns its structured response when it was built with `response_format`,
    otherwise the text of its final message.
    """
    result = agent.invoke({"messages": [{"role": "user", "content": prompt}]})
    if result.get("structured_response") is not None:
        return result["structured_response"]
    return result["messages"][-1].text
